    self.OnRoleChangeEvent = Events.AddListener("MaidCoffee_PersonChange",Bind(self,self.OnSelectRoleChange))
    self.SoulPointRecoverEvent = Events.AddListener("MaidCoffee_RecoverSoulPoint",Bind(self,self.RefreshShowInfo))
end

function OverseaManagePersonnelMainDialog:InitInfo()
    self.clerkEnv = {}
    for i = 1, ClerkCount do
        local clerk = self["Cell"..i]
        if clerk then
            local env =  CfUtils.GetLuaScr(clerk,"Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManagerPersonnelClerkCell")
            env:SetAddCallBack(i)
            self.clerkEnv[i] = env
            KTool.SetActive(clerk.gameObject,false)
        end
    end

