            env:SetAddCallBack(Bind(self,self.OnCatCellClick))
            self.catEnv[i] = env
        end
    end]]
end

function OverseaManagePersonnelMainDialog:AddUIClick()
    SetButtonAction(self.BtnAddShopOwner.gameObject, Bind(self,self.OnBtnAddShopOwnerClick))
    SetButtonAction(self.Button.gameObject, Bind(self,self.OnBtnTipsClick))
    SetButtonAction(self.BtnClerkTip.gameObject, Bind(self,self.OnBtnClerkTipClick))
    --SetButtonAction(self.BtnPrivilege.gameObject,Bind(self,self.OnBtnPrivilegeClick))
end

function OverseaManagePersonnelMainDialog:OnFocus(focus)
    if focus then
        Events.Broadcast("MaidCoffeeRefreshManagerAddStatus",true)
        Events.Broadcast("MaidCoffee_SetManageRotation",-10)
        self:SetNodePosition()
    end
end

function OverseaManagePersonnelMainDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self:SetNodePosition()
        end)
    end))
    return coWait
end

function OverseaManagePersonnelMainDialog:SetNodePosition()
    self:RemovePosCo()
    self.posCo = cs_coroutine.start(function()
        if self.parameters and self.parameters.pos then
            coroutine.yield(Yielders.GetWaitForSeconds(0.7))
            self:RefreshManagerRedPoint()
            local pos = self.parameters.pos
            Events.Broadcast("MaidCoffee_ChangeBarVim",false)
            Events.Broadcast("MaidCoffeeTvNodeChangeState",false)
            if not KTool.IsNull(pos) then
                local scenePos = CfUtils.WorldPosition2UIPosition(pos, UIModule.RootCanvas.transform)
                self.BtnAddShopOwner.transform.anchoredPosition = Vector2.New(scenePos.x, scenePos.y)
            end
        end
    end)
end

function OverseaManagePersonnelMainDialog:RemovePosCo()
    if self.posCo then
        cs_coroutine.stop(self.posCo)
        self.posCo = nil
    end
end

function OverseaManagePersonnelMainDialog:RefreshShowInfo()
    self:RefreshOwnerShow()
    self:RefreshClerkInfo()
end

function OverseaManagePersonnelMainDialog:RefreshOwnerShow()
    local staffInfo = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    local isHaveOwner = (tonumber(staffInfo) ~= 0)
    KTool.SetActive(self.SoulPoint.gameObject,isHaveOwner)
    KTool.SetActive(self.Buff.gameObject,isHaveOwner)
    KTool.SetActive(self.Tips.gameObject,false)
    local vo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(3)
    self.TipTxt.text = localize("每售卖一份套餐消耗心情值：_num_",{_num_ = string.format("<color=#ff2380>%s</color>",vo.num)})
    if isHaveOwner then
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        local cardDojo = cardComponent:GetCardById(tonumber(staffInfo))
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardDojo.cardId)
        self.TextName.text = cardVo.name
        ---设置心情值和状态 会刷新
        local point = tonumber(cardDojo.cafeEnergy) or 0
        self:SetSoulPointAndStatus(point)
        self:RefreshBuffTxt(cardDojo.cardId)
        KTool.SetActive(self.NotEffective.gameObject,point == 0)

        local canvasGroup = self.BuffIcon.transform:GetComponent(typeof(CanvasGroup))
        local alpha = point == 0 and 0.5 or 1
        canvasGroup.alpha = alpha
    end
    Events.Broadcast("MaidCoffeeRefreshManagerAddStatus",true)
end

function OverseaManagePersonnelMainDialog:RefreshManagerRedPoint()
    local redGo = GameUtils.GetRedPointGo(self.BtnAddShopOwner)
    if redGo then
        local isHave = component:IsManagerHaveRedPoint()
        KTool.SetActive(redGo,isHave)
    end

    local isPersonHave = component:IsPersonHaveRedPoint()
    GameUtils.SetRedPointNum(Constants.RedPointConst.MaidCafeStaff,isPersonHave and 1 or 0)
end

---刷新店员信息
function OverseaManagePersonnelMainDialog:RefreshClerkInfo()
    for i = 1, #self.clerkEnv do
        local data = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        KTool.SetActive(self.clerkEnv[i].controller.gameObject,true)
        self.clerkEnv[i]:RefreshCellShow(i,data)
    end

    KTool.SetActive(self.ClerkTips.gameObject,false)
    local vo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(3)
    CfUtils.FillText(self.ClerkTipText,localize("每售卖一份套餐消耗心情值：_num_",{_num_ = string.format("<color=#ff2380>%s</color>",vo.num)}))

end

function OverseaManagePersonnelMainDialog:SetSoulPointAndStatus(point)
    CfUtils.FillText(self.TextNumber,point)
    KTool.SetActive(self.UIFX_warning.gameObject,point < 50)
    local status = MaidCoffeeUtils.GetCardMoodStatus(point)
    CfUtils.SetUISwitchText(self.TextNumber,status)
    CfUtils.SetUISwitchImage(self.ImgAttribute,status)
    CfUtils.SetUISwitchImage(self.ImgBg,status)
end

function OverseaManagePersonnelMainDialog:RefreshBuffTxt(staffId)
    local vo = MaidCoffeeUtils.GetCardManagerInfoVo(staffId)
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(vo.additionId)
    if skillVo then
        local skillDes = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr,vo.additionNum,nil,vo.percentage) or ""
        CfUtils.FillImage(self.ImgIcon,skillVo.icon)
        CfUtils.FillText(self.TextTitle,skillVo.name)
        self.Text.text = skillDes
    end
end

function OverseaManagePersonnelMainDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.parameters = self.controller.Argument.parameters
            GameUtils.Request(Interfaces.MaidCoffeeCardMood1,{},function(request,response)
                if checkInt(response.errCode) == 0 then
                    local responseData = response.data
                    local cardsEnergy = responseData.cardsEnergy
                    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                    for i, v in pairs(cardsEnergy) do
                        local cardDojo = cardComponent:GetCardById(tonumber(i))
                        cardDojo:UpdateCardEnergy(v,true)
                    end
                    Events.Broadcast("MaidCoff.ChangeCardEnergy")
                    self:RefreshShowInfo()
                end
            end)
        end)
    end))
    return coWait
end

function OverseaManagePersonnelMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            Events.Broadcast("MaidCoffeeRefreshManagerAddStatus",false)
            self:RemovePosCo()
            self.parameters = nil
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function OverseaManagePersonnelMainDialog:__delete()
    if self.OnRoleChangeEvent then
        Events.RemoveListener("MaidCoffee_PersonChange",self.OnRoleChangeEvent)
        self.OnRoleChangeEvent = nil
    end
    
    if self.SoulPointRecoverEvent then
        Events.RemoveListener("MaidCoffee_RecoverSoulPoint",self.SoulPointRecoverEvent)
        self.SoulPointRecoverEvent = nil
    end
    self.controller = nil
end


