function OverseaManagePersonnelMainDialog:OnBtnAddShopOwnerClick()
    local haveData = {}
    local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    table.insert(haveData,{index = 1,id = id})
    component:SaveCacheData(haveData)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeePersonSelectDialog , parameters = { type = MaidCoffeeConstants.SelectType.Manager,data = haveData,cb = nil } })
end

function OverseaManagePersonnelMainDialog:OnBtnTipsClick()
    KTool.SetActive(self.Tips.gameObject,not self.Tips.gameObject.activeSelf)
end

function OverseaManagePersonnelMainDialog:OnBtnClerkTipClick()
    KTool.SetActive(self.ClerkTips.gameObject,not self.ClerkTips.gameObject.activeSelf)
end

function OverseaManagePersonnelMainDialog:OnSelectRoleChange(data)
    if data.type == MaidCoffeeConstants.SelectType.Clerk then
        self:RefreshClerkInfo()
    elseif data.type == MaidCoffeeConstants.SelectType.Manager then
        self:RefreshOwnerShow()
        self:RefreshManagerRedPoint()
    end
end

function OverseaManagePersonnelMainDialog:IsHavePrivilegeCard()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo = playerComponent:GetPlayerDojo()
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
    local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
    return isHavePrivilegeCard
end

